gVV(){return"\u0627\u0633\u0645 \u0627\u0644\u0634\u0631\u0643\u0629 / \u0627\u0644\u0645\u062a\u062c\u0631 \u0645\u0637\u0644\u0648\u0628."},
gVI(){return"\u0627\u062e\u062a\u0631 \u0634\u0639\u0627\u0631 \u0634\u0631\u0643\u062a\u0643"},
gVr(){return"\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0647\u0630\u0627 \u0627\u0644\u0644\u0648\u0646"},
gU_(){return"\u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u062d\u0633\u0627\u0628"},
gJA(){return"\u0627\u0633\u0645 \u0627\u0644\u0628\u0646\u0643 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gJy(){return"\u0631\u0642\u0645 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gJC(){return"\u0622\u064a\u0628\u0627\u0646 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gU0(){return'\u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0645\u062b\u0644 "ADCB \u0627\u0644\u062c\u0627\u0631\u064a")'},
