ga3i(){return'\u0645\u062b\u0644 "\u0639\u0647\u062f\u0629 \u0645\u0643\u062a\u0628 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644"'},
ga3f(){return"\u0627\u0644\u0648\u0635\u064a (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
ga3o(){return"\u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u064a"},
gMY(){return"\u0627\u0644\u0645\u0628\u0644\u063a"},
ga3c(){return"\u0627\u0644\u0641\u0626\u0629"},
ga3n(){return"\u0645\u0644\u0627\u062d\u0638\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gYb(){return"\u0627\u0643\u062a\u0628 RESET \u0644\u0644\u062a\u0623\u0643\u064a\u062f"},
gY4(){return"\u0645\u0633\u062d \u0643\u0644 \u0634\u064a\u0621"},
Ya(a){return"\u0641\u0634\u0644\u062a \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0639\u064a\u064a\u0646: "+a},
gY8(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0643\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u061f"},
gY5(){return"\u064a\u0624\u062f\u064a \u0647\u0630\u0627 \u0625\u0644\u0649 \u0645\u062d\u0648 \u0643\u0644 \u0634\u064a\u0621 \u0623\u062f\u062e\u0644\u0647 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u062a\u062c\u0627\u0631\u064a \u0623\u0648 \u0627\u0633\u062a\u0648\u0631\u062f\u0647 \u062d\u0631\u0641\u064a\u064b\u0627: \u0643\u0644 \u0639\u0645\u064a\u0644 \u0648\u0645\u0648\u0631\u062f \u0648\u0635\u0646\u0641 \u0648\u0641\u0627\u062a\u0648\u0631\u0629 \u0648\u0634\u0631\u0627\u0621 \u0648\u0625\u0634\u0639\u0627\u0631 \u0648\u0634\u064a\u0643 \u0648\u062a\u0633\u0644\u064a\u0645 \u0648\u0633\u0646\u062f \u0648\u0642\u064a\u062f \u062f\u0641\u062a\u0631 \u0623\u0633\u062a\u0627\u0630 \u0648\u062d\u0631\u0643\u0629 \u0645\u062e\u0632\u0648\u0646 \u0648\u062d\u0633\u0627\u0628 \u0628\u0646\u0643\u064a \u0648\u0645\u0648\u0638\u0641 \u0648\u0633\u062c\u0644 \u0627\u0644\u062a\u062f\u0642\u064a\u0642.\n\n\u0641\u0642\u0637 \u0627\u0644\u0641\u0631\u0639 (\u0627\u0644\u0641\u0631\u0648\u0639) \u0648\u0645\u0644\u0641 \u0627\u0644\u0634\u0631\u0643\u0629 \u0648\u062a\u0633\u062c\u064a\u0644\u0627\u062a \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u062a\u0646\u062c\u0648 \u2014 \u062d\u062a\u0649 \u062a\u062a\u0645\u0643\u0646 \u0645\u0646 \u0627\u0644\u062f\u062e\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u0643\u0644 \u0634\u064a\u0621 \u0622\u062e\u0631 \u064a\u0639\u0648\u062f \u0641\u0627\u0631\u063a\u064b\u0627\u060c \u062a\u0645\u0627\u0645\u064b\u0627 \u0645\u062b\u0644 \u0634\u0631\u0643\u0629 \u062c\u062f\u064a\u062f\u0629 \u062a\u0645\u0627\u0645\u064b\u0627.\n\n\u0627\u0633\u062a\u062e\u062f\u0645 \u0647\u0630\u0627 \u0644\u0645\u0633\u062d \u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0645\u0643\u0631\u0631 \u0623\u0648 \u0641\u0627\u0633\u062f \u0642\u0628\u0644 \u062a\u0634\u063a\u064a\u0644\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0647\u0630\u0627."},
gY3(){return"\u062a\u0645 \u0645\u0633\u062d \u0643\u0644 \u0633\u062c\u0644 \u062a\u062c\u0627\u0631\u064a \u2014 \u0639\u0627\u062f\u062a \u0627\u0644\u0634\u0631\u0643\u0629 \u0625\u0644\u0649 \u0627\u0644\u0641\u0631\u0627\u063a."},
gY7(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0643\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a"},
gY6(){return"\u0643\u0644 \u0639\u0645\u064a\u0644 \u0648\u0645\u0648\u0631\u062f \u0648\u0635\u0646\u0641 \u0648\u0645\u0639\u0627\u0645\u0644\u0629 \u2014 \u064a\u064f\u0645\u062d\u0649 \u0625\u0644\u0649 \u0634\u0631\u0643\u0629 \u062c\u062f\u064a\u062f\u0629 \u062a\u0645\u0627\u0645\u064b\u0627. \u0641\u0642\u0637 \u0627\u0644\u0641\u0631\u0639 (\u0627\u0644\u0641\u0631\u0648\u0639) \u0648\u0645\u0644\u0641 \u0627\u0644\u0634\u0631\u0643\u0629 \u0648\u062a\u0633\u062c\u064a\u0644\u0627\u062a \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u062a\u0646\u062c\u0648. \u0627\u0633\u062a\u062e\u062f\u0645 \u0647\u0630\u0627 \u0644\u0645\u0633\u062d \u0627\u0633\u062a\u064a\u0631\u0627\u062f \u0645\u0643\u0631\u0631 \u0623\u0648 \u0641\u0627\u0633\u062f \u0642\u0628\u0644 \u062a\u0634\u063a\u064a\u0644\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
gY9(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646"},
